begin;
alter table psicoluz.support_recommendations add column context_fingerprint text not null default '';
create function psicoluz.followup_bundle() returns jsonb language sql immutable set search_path=pg_catalog as $fn$ select '{"model":{"version":"synthetic-softmax-v2","kind":"multinomial-logistic-regression","trained":true,"syntheticOnly":true,"llmTrained":false,"clinicalValidation":false,"classes":["organizacion","instrucciones","comunicacion","lectura","escritura","autonomia"],"features":["recorded_overdue_ratio","completed_ratio","recent_cancelled_appointments_scaled","tag_organizacion","tag_instrucciones","tag_comunicacion","tag_lectura","tag_escritura","tag_autonomia"],"weights":[[-2.517868664165251e-17,-9.025062064050697e-18,-6.292539721865358e-17,4.229756131940621,-0.8459512263881256,-0.8459512263881255,-0.8459512263881255,-0.8459512263881254,-0.8459512263881254],[-7.257317311476196e-18,2.1543696136765212e-17,-2.7356392120151843e-17,-0.8459512263881256,4.229756131940621,-0.8459512263881255,-0.8459512263881255,-0.8459512263881254,-0.8459512263881253],[7.235459546724967e-18,5.021912935503962e-17,-9.090641012790027e-19,-0.8459512263881255,-0.8459512263881255,4.229756131940621,-0.8459512263881254,-0.8459512263881253,-0.8459512263881251],[3.844594877242034e-17,8.957187385483899e-17,1.6695412805861278e-17,-0.8459512263881255,-0.8459512263881255,-0.8459512263881255,4.229756131940621,-0.8459512263881253,-0.8459512263881251],[7.394672587251062e-17,8.955094824336395e-17,5.2990556118662496e-17,-0.8459512263881255,-0.8459512263881255,-0.8459512263881254,-0.8459512263881254,4.22975613194062,-0.8459512263881253],[-3.92196494791472e-17,-4.1744742947134944e-17,-6.501052172571044e-17,-0.8459512263881255,-0.8459512263881255,-0.8459512263881255,-0.8459512263881255,-0.8459512263881254,4.229756131940621]],"bias":[4.052788378332276e-16,3.3047295368987473e-16,1.8124743242711818e-16,2.7452812158962364e-16,3.897598389868134e-16,2.043612674917929e-16],"trainingSamples":96,"testSamples":24,"datasetSha256":{"train":"d1ec9a08a33f2222a12223360096a798d2b5b5246756dabec8f4c245a13a5477","test":"f5314cae22eca66c390444989cf5e8d444de5853fe6bc9a0610926cdeb40d40b"},"hyperparameters":{"epochs":1200,"learningRate":0.3,"l2":0.001},"metrics":{"training":{"samples":96,"correct":96,"accuracy":1,"logLoss":0.03075549487593517,"confusion":[[16,0,0,0,0,0],[0,16,0,0,0,0],[0,0,16,0,0,0],[0,0,0,16,0,0],[0,0,0,0,16,0],[0,0,0,0,0,16]],"classOrder":["organizacion","instrucciones","comunicacion","lectura","escritura","autonomia"]},"heldOut":{"samples":24,"correct":24,"accuracy":1,"logLoss":0.030755494875935246,"confusion":[[4,0,0,0,0,0],[0,4,0,0,0,0],[0,0,4,0,0,0],[0,0,0,4,0,0],[0,0,0,0,4,0],[0,0,0,0,0,4]],"classOrder":["organizacion","instrucciones","comunicacion","lectura","escritura","autonomia"]}},"limitations":"Artificial one-tag scenarios. Not a clinical evaluation or proof of real-world skill recommendation quality."},"rules":{"plan":"Podría ser útil revisar las actividades del plan cuyo cumplimiento sigue pendiente, su dificultad, frecuencia y acompañamiento en casa, antes de asignar nuevas tareas.","continuidad":"Podría ser útil revisar la continuidad de las citas y acordar una rutina de seguimiento de las actividades con la familia.","revision":"Podría ser útil revisar las instrucciones y la fecha de seguimiento del plan con la profesional antes de ajustar las actividades."},"skills":{"organizacion":"Organización de tareas","instrucciones":"Seguimiento de instrucciones","comunicacion":"Comunicación durante la actividad","lectura":"Práctica de lectura","escritura":"Práctica de escritura","autonomia":"Autonomía en la rutina"},"skillTexts":{"organizacion":"Podría considerarse una actividad breve de organización de tareas, seleccionada y adaptada por la profesional a los objetivos del plan de trabajo.","instrucciones":"Podría considerarse una actividad breve de seguimiento de instrucciones, seleccionada y adaptada por la profesional a los objetivos del plan de trabajo.","comunicacion":"Podría considerarse una actividad breve de comunicación durante la actividad, seleccionada y adaptada por la profesional a los objetivos del plan de trabajo.","lectura":"Podría considerarse una actividad breve de práctica de lectura, seleccionada y adaptada por la profesional a los objetivos del plan de trabajo.","escritura":"Podría considerarse una actividad breve de práctica de escritura, seleccionada y adaptada por la profesional a los objetivos del plan de trabajo.","autonomia":"Podría considerarse una actividad breve de autonomía en la rutina, seleccionada y adaptada por la profesional a los objetivos del plan de trabajo."},"ruleVersion":"plan-review-v1"}'::jsonb $fn$;
create function psicoluz.followup_safe_text(t text) returns boolean language sql immutable set search_path=pg_catalog as $$
 select t is not null and length(trim(t)) between 12 and 3000 and normalize(t,NFC) !~* '(diagn[oó]stic|pron[oó]stic|inteligencia|trastorno|d[eé]ficit|retraso|padece|autismo|\mtdah\M|predicci[oó]n)'
$$;
create function psicoluz.followup_context(rid uuid) returns jsonb language plpgsql stable set search_path=pg_catalog as $$
declare c jsonb; src jsonb; versions jsonb; tags jsonb; today date:=(now() at time zone 'America/Managua')::date;
begin
 select coalesce(jsonb_agg(jsonb_build_object('type',case when s.note_id is not null then 'note' else 'evaluation' end,'id',coalesce(s.note_id,s.evaluation_id),'tags',s.tags) order by s.id),'[]'),coalesce(jsonb_agg(jsonb_build_object('id',s.id,'version',coalesce(n.updated_at,e.updated_at)) order by s.id),'[]') into src,versions
 from psicoluz.support_sources s left join psicoluz.notes n on n.id=s.note_id left join psicoluz.evaluations e on e.id=s.evaluation_id where s.record_id=rid and coalesce(n.date,e.date) between today-90 and today;
 select coalesce(jsonb_agg(tag order by tag),'[]') into tags from (select distinct jsonb_array_elements_text(x->'tags') tag from jsonb_array_elements(src) x) q;
 select jsonb_build_object('total',count(*),'active',count(*) filter(where status in ('pendiente','en_proceso')),'overdue',count(*) filter(where status='vencida'),'completed',count(*) filter(where status='cumplida'),'cancelledAppointments',(select count(*) from psicoluz.appointments where record_id=rid and status='cancelada' and (start_at at time zone 'America/Managua')::date between today-90 and today),'tags',tags,'sources',src,'sourceVersions',versions,'revision',(select context_revision from psicoluz.records where id=rid),'bundleHash',md5(psicoluz.followup_bundle()::text)) into c from psicoluz.activities where record_id=rid;
 return (c-'sourceVersions'-'bundleHash')||jsonb_build_object('fingerprint',md5(c::text));
end $$;
create function psicoluz.followup_proposals(c jsonb) returns jsonb language plpgsql immutable set search_path=pg_catalog as $$
declare b jsonb:=psicoluz.followup_bundle(); model jsonb:=b->'model'; result jsonb:='[]'; candidates jsonb:='[]'; item jsonb; skill text; label text; logits double precision[]; probs double precision[]; features double precision[]; v double precision; mx double precision; denom double precision; j integer; k integer; n integer;
begin
 if coalesce((c->>'total')::integer,0)=0 then return '[]'::jsonb;end if;
 if (c->>'overdue')::integer>0 then result:=result||jsonb_build_array(jsonb_build_object('ruleId','plan','title','Revisar el plan de actividades','text',b->'rules'->>'plan','basis',(c->>'active')||' actividades vigentes y '||(c->>'overdue')||' vencidas registradas.','origin','Regla de revisión del plan'));end if;
 if (c->>'cancelledAppointments')::integer>0 then result:=result||jsonb_build_array(jsonb_build_object('ruleId','continuidad','title','Revisar la continuidad del seguimiento','text',b->'rules'->>'continuidad','basis',(c->>'cancelledAppointments')||' citas canceladas en los últimos 90 días.','origin','Regla de continuidad'));end if;
 for j in 0..5 loop
   skill:=model->'classes'->>j;if not (c->'tags') ? skill then continue;end if;
   features:=array[(c->>'overdue')::double precision/greatest((c->>'total')::integer,1),(c->>'completed')::double precision/greatest((c->>'total')::integer,1),least((c->>'cancelledAppointments')::integer,3)::double precision/3,0,0,0,0,0,0];features[j+4]:=1;logits:=array[]::double precision[];
   for n in 0..5 loop v:=(model->'bias'->>n)::double precision;for k in 0..8 loop v:=v+(model->'weights'->n->>k)::double precision*features[k+1];end loop;logits:=array_append(logits,v);end loop;
   select max(z) into mx from unnest(logits) z;probs:=array[]::double precision[];denom:=0;for n in 1..6 loop v:=exp(logits[n]-mx);probs:=array_append(probs,v);denom:=denom+v;end loop;
   if logits[j+1]<>mx then continue;end if; label:=b->'skills'->>skill;
   candidates:=candidates||jsonb_build_array(jsonb_build_object('ord',j,'score',probs[j+1]/denom,'ruleId','skill-'||skill,'title',label,'text',b->'skillTexts'->>skill,'basis','Etiqueta seleccionada expresamente por la profesional en el contexto de apoyo.','origin','Modelo entrenado · '||(model->>'version')));
 end loop;
 for item in select value from jsonb_array_elements(candidates) order by (value->>'score')::double precision desc,(value->>'ord')::integer limit 2 loop result:=result||jsonb_build_array(item-'score'-'ord');end loop;
 if jsonb_array_length(result)=0 then result:=jsonb_build_array(jsonb_build_object('ruleId','revision','title','Revisar el seguimiento del plan','text',b->'rules'->>'revision','basis',(c->>'total')||' actividades registradas; sin evidencia para inferir una evolución clínica.','origin','Regla de revisión'));end if;
 return (select jsonb_agg(value order by ord) from (select value,ord from jsonb_array_elements(result) with ordinality x(value,ord) order by ord limit 3) q);
end $$;
create function psicoluz.followup_activity(a psicoluz.activities) returns jsonb language sql stable set search_path=pg_catalog as $$
 select jsonb_build_object('id',a.id,'recordId',a.record_id,'title',a.title,'description',a.description,'instructions',a.instructions,'priority',a.priority,'followUpDate',a.follow_up_date,'status',a.status,'visiblePortal',a.visible_portal,'noteId',a.note_id,'authorId',a.author_id,'createdAt',a.created_at,'updatedAt',a.updated_at)
$$;
create function psicoluz.followup_family(rid uuid) returns jsonb language sql stable set search_path=pg_catalog as $$
 select jsonb_build_object('activities',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'description',a.description,'instructions',a.instructions,'priority',a.priority,'followUpDate',a.follow_up_date,'status',a.status) order by a.follow_up_date,a.id) from psicoluz.activities a where a.record_id=rid and a.visible_portal and a.family_authorized_by is not null and a.family_authorized_at is not null),'[]'),'recommendations',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'text',s.reviewed_text) order by s.created_at,s.id) from psicoluz.support_recommendations s join psicoluz.records r on r.id=s.record_id where r.id=rid and r.support_enabled and s.status='aceptada' and not s.archived and s.visible_portal and s.reviewed_by is not null and s.context_revision=r.context_revision and s.context_fingerprint=psicoluz.followup_context(rid)->>'fingerprint' and psicoluz.followup_safe_text(s.reviewed_text)),'[]'))
$$;
create function psicoluz.followup_publication_guard() returns trigger language plpgsql set search_path=pg_catalog as $$
begin
 if new.visible_portal and (not psicoluz.followup_safe_text(new.reviewed_text) or new.context_fingerprint is distinct from (psicoluz.followup_context(new.record_id)->>'fingerprint') or new.model_version is distinct from (psicoluz.followup_bundle()->'model'->>'version') or new.rule_version is distinct from (psicoluz.followup_bundle()->>'ruleVersion')) then raise exception 'Requiere actualización y revisión profesional.' using errcode='23514';end if;return new;
end $$;
create trigger followup_publication before insert or update on psicoluz.support_recommendations for each row execute function psicoluz.followup_publication_guard();
create function public.psicoluz_seguimiento(p_action text,p_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare actor psicoluz.staff_profiles%rowtype; r psicoluz.records%rowtype; a psicoluz.activities%rowtype; s psicoluz.support_recommendations%rowtype; n psicoluz.notes%rowtype; e psicoluz.evaluations%rowtype; l psicoluz.resource_links%rowtype; allowed text[]; c jsonb; result jsonb; item jsonb; sources jsonb; tags text[]; nid uuid; eid uuid; is_visible boolean; created integer:=0; today date:=(now() at time zone 'America/Managua')::date;
begin
 select * into actor from psicoluz.staff_profiles where id=auth.uid() and active for share;
 if not found or actor.role<>'psicologa' then raise exception 'Acceso reservado a la profesional responsable.' using errcode='42501';end if;
 if p_action is null or p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'Solicitud no válida.' using errcode='22023';end if;
 allowed:=case p_action when 'list' then array[]::text[] when 'open' then array['record_id'] when 'family' then array['record_id']
 when 'activity' then array['record_id','id','expected_revision','expected_updated_at','title','description','instructions','priority','follow_up_date','status','visible_portal','confirm_visible','note_id']
 when 'status' then array['record_id','id','expected_revision','expected_updated_at','status']
 when 'link' then array['record_id','id','expected_revision','expected_updated_at','title','description','url','visible_portal','confirm_visible']
 when 'configure' then array['record_id','expected_revision','enabled','sources'] when 'generate' then array['record_id','expected_revision']
 when 'review' then array['record_id','id','expected_revision','expected_updated_at','decision','text','confirm_review','visible_portal','confirm_visible'] when 'rate' then array['record_id','id','expected_revision','expected_updated_at','rating']
 when 'note' then array['record_id','id','expected_revision','expected_updated_at','title','body','date','visibility','confirm_visible'] when 'evaluation' then array['record_id','id','expected_revision','expected_updated_at','type','date','summary'] else null end;
 if allowed is null or exists(select 1 from jsonb_each(p_payload) q where not q.key=any(allowed) or case when q.key='expected_revision' then jsonb_typeof(q.value)<>'number' when q.key in ('visible_portal','confirm_visible','confirm_review','enabled') then jsonb_typeof(q.value)<>'boolean' when q.key='sources' then jsonb_typeof(q.value)<>'array' when q.key='note_id' then jsonb_typeof(q.value) not in ('string','null') else jsonb_typeof(q.value)<>'string' end) then raise exception 'Campos no permitidos.' using errcode='22023';end if;
 if p_action='list' then
  insert into psicoluz.audit_events(actor_user_id,operation,entity)values(actor.id,'FOLLOWUP_INDEX','records');
  return coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'number',v.number,'patientName',p.first_name||' '||p.last_name,'professionalId',v.professional_id,'contextRevision',v.context_revision,'activities',coalesce((select jsonb_agg(psicoluz.followup_activity(x) order by x.follow_up_date,x.id) from psicoluz.activities x where x.record_id=v.id),'[]')) order by p.last_name,v.number) from psicoluz.records v join psicoluz.patients p on p.id=v.patient_id where v.professional_id=actor.id),'[]');
 end if;
 select * into r from psicoluz.records where id=(p_payload->>'record_id')::uuid and professional_id=actor.id for update;
 if not found then raise exception 'Expediente no disponible.' using errcode='42501';end if;
 c:=psicoluz.followup_context(r.id);
 update psicoluz.support_recommendations set archived=true,visible_portal=false where record_id=r.id and not archived and (context_fingerprint is distinct from c->>'fingerprint' or model_version is distinct from (psicoluz.followup_bundle()->'model'->>'version') or rule_version is distinct from (psicoluz.followup_bundle()->>'ruleVersion'));
 if p_action in ('open','family') then
  insert into psicoluz.audit_events(actor_user_id,operation,entity,entity_id)values(actor.id,case when p_action='family' then 'FAMILY_PREVIEW' else 'FOLLOWUP_VIEW' end,'records',r.id);
  if p_action='family' then return psicoluz.followup_family(r.id);end if;
  return jsonb_build_object('id',r.id,'number',r.number,'patientName',(select first_name||' '||last_name from psicoluz.patients where id=r.patient_id),'contextRevision',r.context_revision,
  'activities',coalesce((select jsonb_agg(psicoluz.followup_activity(x) order by x.follow_up_date,x.id) from psicoluz.activities x where x.record_id=r.id),'[]'),
  'notes',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'recordId',x.record_id,'title',x.title,'body',x.body,'date',x.date,'visibility',x.visibility,'authorId',x.author_id,'createdAt',x.created_at,'updatedAt',x.updated_at) order by x.date desc,x.id) from psicoluz.notes x where x.record_id=r.id),'[]'),
  'evaluations',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'recordId',x.record_id,'type',x.type,'date',x.date,'summary',x.summary,'authorId',x.author_id,'createdAt',x.created_at,'updatedAt',x.updated_at) order by x.date desc,x.id) from psicoluz.evaluations x where x.record_id=r.id),'[]'),
  'links',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'recordId',x.record_id,'title',x.title,'description',x.description,'url',x.url,'visiblePortal',x.visible_portal,'updatedAt',x.updated_at,'createdAt',x.created_at) order by x.created_at,x.id) from psicoluz.resource_links x where x.record_id=r.id),'[]'),
  'reports',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'activityId',x.activity_id,'outcome',x.outcome,'message',x.message,'at',x.created_at) order by x.created_at desc,x.id) from psicoluz.family_reports x where x.record_id=r.id),'[]'),
  'support',jsonb_build_object('enabled',r.support_enabled,'sources',c->'sources'),'context',c,
  'recommendations',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'recordId',x.record_id,'ruleId',x.rule_id,'title',x.title,'text',x.draft_text,'basis',x.basis,'origin',case when x.rule_id like 'skill-%' then 'Modelo entrenado · '||x.model_version else 'Regla de revisión del plan' end,'status',x.status,'visiblePortal',x.visible_portal,'reviewedText',x.reviewed_text,'reviewedBy',x.reviewed_by,'rating',x.rating,'archived',x.archived,'stale',x.context_fingerprint is distinct from c->>'fingerprint','modelVersion',x.model_version,'ruleVersion',x.rule_version,'createdAt',x.created_at,'updatedAt',x.updated_at) order by x.created_at desc,x.id) from psicoluz.support_recommendations x where x.record_id=r.id),'[]'),
  'history',coalesce((select jsonb_agg(jsonb_build_object('id',x.id::text,'actor',coalesce(sp.display_name,'Personal autorizado'),'action',x.operation||' · '||x.entity,'at',x.at) order by x.at desc,x.id desc) from psicoluz.audit_events x left join psicoluz.staff_profiles sp on sp.id=x.actor_user_id where (x.entity='records' and x.entity_id=r.id) or (x.entity='activities' and x.entity_id in(select id from psicoluz.activities where record_id=r.id)) or (x.entity='notes' and x.entity_id in(select id from psicoluz.notes where record_id=r.id)) or (x.entity='evaluations' and x.entity_id in(select id from psicoluz.evaluations where record_id=r.id)) or (x.entity='support_recommendations' and x.entity_id in(select id from psicoluz.support_recommendations where record_id=r.id)) or (x.entity='resource_links' and x.entity_id in(select id from psicoluz.resource_links where record_id=r.id))),'[]'),
  'family',psicoluz.followup_family(r.id));
 end if;
 if (p_payload->>'expected_revision')::bigint is distinct from r.context_revision then raise exception 'El expediente cambió. Volvé a cargar antes de guardar.' using errcode='40001';end if;
 is_visible:=coalesce((p_payload->>'visible_portal')::boolean,false);
 if (p_action in ('activity','link','review') and is_visible or p_action='note' and p_payload->>'visibility'='paciente_tutor') and not coalesce((p_payload->>'confirm_visible')::boolean,false) then raise exception 'Confirmá la autorización familiar.' using errcode='22023';end if;
 if p_action in ('activity','status') then
  if nullif(p_payload->>'id','') is not null then select * into a from psicoluz.activities where id=(p_payload->>'id')::uuid and record_id=r.id for update;if not found then raise exception 'Actividad no disponible.' using errcode='42501';end if;if a.updated_at is distinct from (p_payload->>'expected_updated_at')::timestamptz then raise exception 'Actividad modificada.' using errcode='40001';end if;end if;
  if p_action='status' then if a.id is null then raise exception 'Actividad requerida.' using errcode='22023';end if;update psicoluz.activities set status=p_payload->>'status' where id=a.id;
  else
   nid:=nullif(p_payload->>'note_id','')::uuid;if nid is not null and not exists(select 1 from psicoluz.notes where id=nid and record_id=r.id) then raise exception 'Nota no disponible.' using errcode='42501';end if;
   if a.id is null then insert into psicoluz.activities(record_id,title,description,instructions,priority,follow_up_date,status,visible_portal,note_id,author_id,family_authorized_by,family_authorized_at) values(r.id,trim(p_payload->>'title'),trim(p_payload->>'description'),trim(p_payload->>'instructions'),p_payload->>'priority',(p_payload->>'follow_up_date')::date,p_payload->>'status',is_visible,nid,actor.id,case when is_visible then actor.id end,case when is_visible then now() end);
   else update psicoluz.activities set title=trim(p_payload->>'title'),description=trim(p_payload->>'description'),instructions=trim(p_payload->>'instructions'),priority=p_payload->>'priority',follow_up_date=(p_payload->>'follow_up_date')::date,status=p_payload->>'status',visible_portal=is_visible,note_id=nid,family_authorized_by=case when is_visible then actor.id end,family_authorized_at=case when is_visible then now() end where id=a.id;end if;
  end if;
 elsif p_action='note' then
  if (p_payload->>'date')::date>today then raise exception 'Fecha de sesión no válida.' using errcode='22023';end if;
  if nullif(p_payload->>'id','') is not null then select * into n from psicoluz.notes where id=(p_payload->>'id')::uuid and record_id=r.id for update;if not found then raise exception 'Nota no disponible.' using errcode='42501';end if;if n.updated_at is distinct from (p_payload->>'expected_updated_at')::timestamptz then raise exception 'Nota modificada.' using errcode='40001';end if;end if;
  is_visible:=p_payload->>'visibility'='paciente_tutor';
  if n.id is null then insert into psicoluz.notes(record_id,title,body,date,visibility,author_id,family_authorized_by,family_authorized_at)values(r.id,trim(p_payload->>'title'),trim(p_payload->>'body'),(p_payload->>'date')::date,p_payload->>'visibility',actor.id,case when is_visible then actor.id end,case when is_visible then now() end);
  else update psicoluz.notes set title=trim(p_payload->>'title'),body=trim(p_payload->>'body'),date=(p_payload->>'date')::date,visibility=p_payload->>'visibility',family_authorized_by=case when is_visible then actor.id end,family_authorized_at=case when is_visible then now() end where id=n.id;end if;
 elsif p_action='evaluation' then
  if (p_payload->>'date')::date>today then raise exception 'Fecha de evaluación no válida.' using errcode='22023';end if;
  if nullif(p_payload->>'id','') is not null then select * into e from psicoluz.evaluations where id=(p_payload->>'id')::uuid and record_id=r.id for update;if not found then raise exception 'Evaluación no disponible.' using errcode='42501';end if;if e.updated_at is distinct from (p_payload->>'expected_updated_at')::timestamptz then raise exception 'Evaluación modificada.' using errcode='40001';end if;end if;
  if e.id is null then insert into psicoluz.evaluations(record_id,type,date,summary,author_id)values(r.id,p_payload->>'type',(p_payload->>'date')::date,trim(p_payload->>'summary'),actor.id);else update psicoluz.evaluations set type=p_payload->>'type',date=(p_payload->>'date')::date,summary=trim(p_payload->>'summary') where id=e.id;end if;
 elsif p_action='link' then
  if p_payload->>'url' is null or (p_payload->>'url')!~'^https://[A-Za-z0-9][A-Za-z0-9.-]*(:[0-9]{1,5})?([/?#][^[:space:]<>"\\]*)?$' then raise exception 'Usá un enlace HTTPS sin credenciales.' using errcode='22023';end if;
  if nullif(p_payload->>'id','') is not null then select * into l from psicoluz.resource_links where id=(p_payload->>'id')::uuid and record_id=r.id for update;if not found then raise exception 'Enlace no disponible.' using errcode='42501';end if;if l.updated_at is distinct from (p_payload->>'expected_updated_at')::timestamptz then raise exception 'Enlace modificado.' using errcode='40001';end if;end if;
  if l.id is null then insert into psicoluz.resource_links(record_id,title,description,url,visible_portal,author_id,family_authorized_by,family_authorized_at)values(r.id,trim(p_payload->>'title'),trim(coalesce(p_payload->>'description','')),p_payload->>'url',is_visible,actor.id,case when is_visible then actor.id end,case when is_visible then now() end);
  else update psicoluz.resource_links set title=trim(p_payload->>'title'),description=trim(coalesce(p_payload->>'description','')),url=p_payload->>'url',visible_portal=is_visible,family_authorized_by=case when is_visible then actor.id end,family_authorized_at=case when is_visible then now() end where id=l.id;end if;
 elsif p_action='configure' then
  if not p_payload ? 'enabled' then raise exception 'Estado requerido.' using errcode='22023';end if;
  if (p_payload->>'enabled')::boolean and p_payload ? 'sources' then
   sources:=p_payload->'sources';if jsonb_array_length(sources)>20 then raise exception 'Demasiadas fuentes.' using errcode='22023';end if;
   if (select count(*) from jsonb_array_elements(sources))<>(select count(distinct (x->>'type',x->>'id')) from jsonb_array_elements(sources) x) then raise exception 'Fuentes duplicadas.' using errcode='22023';end if;
   delete from psicoluz.support_sources where record_id=r.id;
   for item in select value from jsonb_array_elements(sources) loop
    if jsonb_typeof(item)<>'object' or not(item ?& array['type','id','tags']) or exists(select 1 from jsonb_object_keys(item) k where k not in ('type','id','tags')) or jsonb_typeof(item->'tags')<>'array' then raise exception 'Fuente no válida.' using errcode='22023';end if;
    nid:=null;eid:=null;tags:=array(select jsonb_array_elements_text(item->'tags'));
    if item->>'type'='note' then nid:=(item->>'id')::uuid;if not exists(select 1 from psicoluz.notes where id=nid and record_id=r.id and date between today-90 and today) then raise exception 'Nota reciente no disponible.' using errcode='42501';end if;
    elsif item->>'type'='evaluation' then eid:=(item->>'id')::uuid;if not exists(select 1 from psicoluz.evaluations where id=eid and record_id=r.id and date between today-90 and today) then raise exception 'Evaluación reciente no disponible.' using errcode='42501';end if;
    else raise exception 'Tipo de fuente no válido.' using errcode='22023';end if;
    insert into psicoluz.support_sources(record_id,note_id,evaluation_id,tags,selected_by)values(r.id,nid,eid,tags,actor.id);
   end loop;
  end if;
  update psicoluz.records set support_enabled=(p_payload->>'enabled')::boolean,context_revision=context_revision+1 where id=r.id;
 elsif p_action='generate' then
  if not r.support_enabled then raise exception 'Apoyo desactivado.' using errcode='23514';end if;
  for item in select value from jsonb_array_elements(psicoluz.followup_proposals(c)) loop
   exit when (select count(*) from psicoluz.support_recommendations where record_id=r.id and not archived and status<>'descartada')>=3;
   if exists(select 1 from psicoluz.support_recommendations where record_id=r.id and not archived and status<>'descartada' and rule_id=item->>'ruleId') then continue;end if;
   if not psicoluz.followup_safe_text(item->>'text') then raise exception 'Catálogo de apoyo no válido.' using errcode='23514';end if;
   insert into psicoluz.support_recommendations(record_id,rule_id,title,draft_text,basis,model_version,rule_version,context_revision,context_fingerprint) values(r.id,item->>'ruleId',item->>'title',item->>'text',item->>'basis',psicoluz.followup_bundle()->'model'->>'version',psicoluz.followup_bundle()->>'ruleVersion',r.context_revision,c->>'fingerprint');created:=created+1;
  end loop;
 elsif p_action in ('review','rate') then
  select * into s from psicoluz.support_recommendations where id=(p_payload->>'id')::uuid and record_id=r.id and not archived for update;
  if not found or not r.support_enabled or s.context_fingerprint is distinct from c->>'fingerprint' then raise exception 'Borrador no disponible. Actualizá el contexto.' using errcode='42501';end if;
  if s.updated_at is distinct from (p_payload->>'expected_updated_at')::timestamptz then raise exception 'La recomendación cambió.' using errcode='40001';end if;
  if p_action='rate' then if s.status='pendiente' or p_payload->>'rating' is null or p_payload->>'rating' not in ('util','parcial','no_util') then raise exception 'Valorá una recomendación revisada.' using errcode='22023';end if;update psicoluz.support_recommendations set rating=p_payload->>'rating' where id=s.id;
  elsif p_payload->>'decision'='descartar' then update psicoluz.support_recommendations set status='descartada',visible_portal=false,reviewed_by=actor.id,reviewed_at=now() where id=s.id;
  elsif p_payload->>'decision'='aceptar' then
   if s.status='descartada' or not coalesce((p_payload->>'confirm_review')::boolean,false) or not psicoluz.followup_safe_text(p_payload->>'text') then raise exception 'Revisá el texto y confirmá la decisión profesional.' using errcode='22023';end if;
   update psicoluz.support_recommendations set status='aceptada',reviewed_text=trim(p_payload->>'text'),reviewed_by=actor.id,reviewed_at=now(),visible_portal=is_visible where id=s.id;
  else raise exception 'Decisión no válida.' using errcode='22023';end if;
 end if;
 insert into psicoluz.audit_events(actor_user_id,operation,entity,entity_id) values(actor.id,'FOLLOWUP_'||upper(p_action),'records',r.id);
 return jsonb_build_object('contextRevision',(select context_revision from psicoluz.records where id=r.id),'created',created);
end $$;
revoke all on function psicoluz.followup_bundle(),psicoluz.followup_safe_text(text),psicoluz.followup_context(uuid),psicoluz.followup_proposals(jsonb),psicoluz.followup_activity(psicoluz.activities),psicoluz.followup_family(uuid),psicoluz.followup_publication_guard() from public,anon,authenticated;
revoke all on function public.psicoluz_seguimiento(text,jsonb) from public,anon,authenticated;
grant execute on function public.psicoluz_seguimiento(text,jsonb) to authenticated;
notify pgrst,'reload schema';
commit;
